// TH14 v1.00b Extra 中Boss 第3组合，源 spellEx109「弦楽「浄瑠璃世界」」。
// source st07mbs.ecl.txt: MBoss3 326-362 / MBoss3B 364-398 / MBossCard3 563-603 /
// MBossCard3B 605-630 / MBossCard3_at 656-679 / MBossCard3B_at 632-654.
// 同一组合生命周期建立两实体：主 I3=0 (-128,160) 与副 I3=10000 (128,160)，
// GI0 为共享完成屏障；两侧各按自己的 2400 超时进 Suspend，GI0>=2 才收组合。

const TIME_LIMIT: int = 2944;
const SPELL_ID: int = 109;
const SPELL_BONUS: int = 500000;
const CARD_LIMIT: int = 2400;      // source spellEx/setInterrupt 2400
const WRAPPER_WAIT: int = 120;     // source wrapper setInvuln(120)/wait(120)
const GVAR_GI0: int = 16;          // source $GI0，自由段槽

const NOTE_COLOR: int = 0;
const TH14_NOTE_RED: int = 976;    // transcribe/th14/touhou-bullets.ecl
const TH14_NOTE_BLUE: int = 992;

// MBossCard3_at 的 EX：ANIM(a=1，出生阶段省略、退位移在出生点执行)，BOUNCE(a=1,b=13)，
// ANGLE_ACCEL(async,a=120,r=0.01,s=0)。源 b=U|L|R=13，目标 左/右/上=1/2/4 -> 7。
xformdef MB3_STRAIGHT {
    bounce_arm(7, 1);
    @120 set_accel(0.01fx);
    set_accel(0fx);
}

// MBossCard3B_at 的 EX：BOUNCE(a=1,b=13)，ANGLE_ACCEL(a=200,r=0.012,s=±0.011635528)。
// 0.011635528 rad/帧 ≈ 121 BAM/帧；两向按调用者参数各写一份。
xformdef MB3_CURVE_CW {
    bounce_arm(7, 1);
    set_ang_vel((0 - 121) as angle);
    @200 set_accel(0.012fx);
    set_accel(0fx);
    set_ang_vel(0deg);
}

xformdef MB3_CURVE_CCW {
    bounce_arm(7, 1);
    set_ang_vel(121 as angle);
    @200 set_accel(0.012fx);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// 源 wait 被本段 2400 中断截断：等待不得越过 deadline。
sub wait_card(n: int, deadline: int) {
    var t: int = $frame + n;
    if t > deadline { t = deadline; }
    while $frame < t { wait(1); }
}

// MBossCard3_at：300 发、间隔 2 帧；%C 起始 RANDRAD，每次 +%B。etAngle 的 0.048706863
// 第二角在 1 路 mode1 下不参与（F(1,0)=0）。etNew/etSprite(type,$A,0)/etCount(1,1)/etSpeed(1.4,1.0)。
sub mb3_straight(shape: int, drift: angle, deadline: int) {
    var c: angle = (rand(65536) - 32768) as angle;
    var k: int = 0;
    while k < 300 && $frame < deadline {
        // ANIM a=1 的 4*速度 退位移：position -= 4 * (1.4 * dir)
        var bx: fx = $self_x - 5.6fx * cos(c);
        var by: fx = $self_y - 5.6fx * sin(c);
        _ = fire(shape, NOTE_COLOR, bx, by, 1.4fx, c, MB3_STRAIGHT, none);
        c = c + drift;
        k = k + 1;
        wait(2);
    }
}

// MBossCard3B_at：200 发、间隔 3 帧；%C 起始 RANDRAD，每次 +3.883222rad ± RANDF2*3deg。
// 3.883222rad ≈ 40504 BAM；RANDF2∈[-1,1] -> ±546 BAM。
sub mb3_curve(shape: int, dir: int, deadline: int) {
    var c: angle = (rand(65536) - 32768) as angle;
    var k: int = 0;
    while k < 200 && $frame < deadline {
        var r: int = rand(65536);
        var step: int = 40504 + ((r - 32768) * 546) / 32768;
        var bx: fx = $self_x - 5.6fx * cos(c);
        var by: fx = $self_y - 5.6fx * sin(c);
        if dir > 0 {
            _ = fire(shape, NOTE_COLOR, bx, by, 1.4fx, c, MB3_CURVE_CCW, none);
        } else {
            _ = fire(shape, NOTE_COLOR, bx, by, 1.4fx, c, MB3_CURVE_CW, none);
        }
        c = c + (step as angle);
        k = k + 1;
        wait(3);
    }
}

// MBossSuspend3（800-825），止于 MBossDead 之前：GI0 递增、broadcastInterrupt(0)
//（本卡无 async 子任务，等价 no-op）、movePosTime(120,1,0,-64)、GI0>=2 屏障。
sub mb3_suspend() {
    set_global(GVAR_GI0, global(GVAR_GI0) + 1);
    move_to(120, 0fx, -64fx, EASE_QUAD_IN);
    while global(GVAR_GI0) < 2 { wait(1); }
}

// 源 MBoss3 侧（I3=0）：lifeSet3000、清移动、60帧到(-128,160)、setInvuln(120)、wait120、
// moveLimit(0,128,280,96)，随后 MBossCard3（566 timerReset 重设 2400 计时基点）。
async sub mboss_main() {
    set_invuln(65535);                 // 独立无敌外壳；源 setInvuln(120) 不用于训练外壳
    set_hitbox(48fx);                  // MBoss 上下文 setHitbox(48,48)
    set_hurtbox(48fx);
    move_to(60, -128fx, 160fx, EASE_QUAD_OUT);
    wait(WRAPPER_WAIT);
    // MBossCard3 入口
    var deadline: int = $frame + CARD_LIMIT;
    set_global(GVAR_GI0, 0);           // 源 582
    spell_begin(0, SPELL_ID, none, TIME_LIMIT, SPELL_BONUS, SPELL_NO_CLEAR, 0);
    wait(60);                          // 源 583；源 +90 时间标签在本时钟基底上已满足
    loop {
        // MBossCard3_at(38, (-%RANDF)*0.05235988 - 0.10471976)
        var u: int = rand(65536);
        mb3_straight(TH14_NOTE_RED, (0 - (1092 + (u * 546) / 65536)) as angle, deadline);
        if $frame >= deadline { break; }
        wait_card(60, deadline);
        if $frame >= deadline { break; }
        // MBossCard3B_at(38, 0.011635528)
        mb3_curve(TH14_NOTE_RED, 1, deadline);
        if $frame >= deadline { break; }
        wait_card(60, deadline);
        if $frame >= deadline { break; }
    }
    mb3_suspend();
    spell_end();                       // GI0>=2：本组合结束（不启动 MBossDead）
    loop { wait(1); }
}

// 源 MBoss3B 侧（I3=10000）：lifeSet3000、setInvuln(120)、374 timerReset（2400 基点在这里）、
// 清移动、60帧到(128,160)、wait120、moveLimit，随后 MBossCard3B（无二次 timerReset）。
async sub mboss_sub() {
    set_invuln(65535);
    set_hitbox(48fx);
    set_hurtbox(48fx);
    var deadline: int = $frame + CARD_LIMIT;
    move_to(60, 128fx, 160fx, EASE_QUAD_OUT);
    wait(WRAPPER_WAIT);
    // MBossCard3B 入口；源 +90 时间标签已越过，无额外等待
    wait(60);                          // 源 610
    loop {
        // MBossCard3B_at(39, -0.011635528)
        mb3_curve(TH14_NOTE_BLUE, -1, deadline);
        if $frame >= deadline { break; }
        wait_card(60, deadline);
        if $frame >= deadline { break; }
        // MBossCard3_at(39, %RANDF*0.05235988 + 0.10471976)
        var u: int = rand(65536);
        mb3_straight(TH14_NOTE_BLUE, (1092 + (u * 546) / 65536) as angle, deadline);
        if $frame >= deadline { break; }
        wait_card(60, deadline);
        if $frame >= deadline { break; }
    }
    mb3_suspend();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(-128fx, 160fx, 3000, 0, 0, 0, mboss_main);
    _ = spawn_enemy(128fx, 160fx, 3000, 0, 0, 0, mboss_sub);
    loop { wait(600); }
}
